    mezmurPoem:
      "እምሄሶ ለሄሮድስ ይብላዕ መሀላሁ\n(2×)\nእም ያምትር ርዕሶ ለዮሐንስ\nአቢይ ነብይ (2×) ሰባኬ ጥምቀት\n(2×)\n\nየመስቀል መዝሙራት",
