    title: "መስቀል ቤዛችን ነው",
    description: null,
    categoryId: 2,
    mezmurPoem:
      "መስቀል ቤዛችን ነው ድል መንሻ\nሃይላችን (2×)\nከሃጢአት በሽታ የሚፈዉሰን (2×)\nበሃጢአት ጨለማ ተውጠን ሳለን\n(2×)\nየክርስቶስ መስቀል ብርሀን ሆነልን\n(2×)\nእንድንመስለው ጌታችንን (2×)\nእንሸከመው ዕፀ መስቀሉን (2×)\nእንድንሸከም ዕፀ መስቀሉን (2×)\nሰውነታችንን ማንፃት አለብን (2×)",
    createdAt: "2026-01-10T08:00:00.000Z",
