    description: null,
    categoryId: 2,
    mezmurPoem: "ዕሌኒ ንግሥት ሐሠሠት መስቀሉ\nዕንባቆም ነቢይ ዘአንከረ ክብሩ/4/",
    createdAt: "2026-01-10T08:00:00.000Z",
    updatedAt: "2026-01-10T08:00:00.000Z",
