    description: null,
    categoryId: 3,
    mezmurPoem:
      "አዘክሪ ድንግል አዘክሪ\nለልጅሽ አሳስቢ አዘክሪ\nለኃጥአን አኮ ለጻድቃን\nአ.ዝ-------------------ከአንቺ መወለዱን አዘክሪ\nበቤተለልሔም ” ”\nበጨርቅ መጠቅለሉን ” ”\nመኝታው ግርግም ” ”\nለኃጥአን (2×) አኮ ለጻድቃን\nአ.ዝ---------------በዚያ በብርድ ወራት አዘክሪ\nየገበሩለትን\n” ”\nየሃድግና የላም ” ”\n\nእስትንፋሳቸው ” ”\nለኃጥአን (2×) አኮ ለጻድቃን\nአ.ዝ-------------በግብጽ በረሃ አዘክሪ\nመሰደድሽን ” ”\nየአሸዋውን ግለት ” ”\nረሃብና ጥሙን ” ”\nለኃጥአን (2×) አኮ ለጻድቃን\nአ.ዝ-----------------በመቃብሩ ዘንድ አዘክሪ\nባለቀሽው እንባ ” ”\nአሳስቢ ድንግል ሆይ ” ”\nገነት እንድገባ ” ”\nለኃጥአን (2×) አኮ ለጻድቃን",
