    description: null,
    categoryId: 4,
    mezmurPoem:
      "ገብርኤል ነው አስደሣች መላዕክ\nአብሳሪሃ ለእመ አምላክ\nቂርቆስ እና እናቱ ከእሳት ሲጣሉ\nዉሀ ሆነ ጠፋ ነበልባሉ\nቤተመቅደስ ስትኖር ድንግል\nእመቤት\nአበሰራት የአምላክን ልደት\nሠለስቱ ደቂቅ ከእሳት ሲጣሉ\nውሀ ሆነ ጠፋ ነበልባሉ\nሠለስቱ ደቂቅን ከእሳት ያዳነ\nገብርኤል ዛሬም ያድነነ",
