    title: "ገብርኤል ኃያል",
    description: null,
    categoryId: 4,
    mezmurPoem:
      "ገብርኤል ኃያል መላከ ሰላም መላከ\nብስራት\nየምታወጣ የእግዚአብሔርን ህዝብ\nከሚነድ እሳት\nፍቅርህ ተስሉዋል በልባችን\nፊትህ ቆመናል ባርከን ብለን\nየፅናታቸው ዝናው ሲሰማ\nከዚያች ቢያብሎን ከሞት ከተማ\nህፃናት ሳሉ በራ እምነታቸው\nቁመህ ተገኘህ መሀከላቸው\nአዝ.........\nውሀው ሲዘልል ቢያስደነግጥም\nበጋኖቹም ውስጥ ቢነዋወጥም\nፀንተው ዘመሩ ልጅና እናቱ\nአንተ ስትደርስ ከዚያ ከሳቱ\nአዝ..........\nቂርቆስም ፀና ሞትን ሳይፈራ\nአንተ ስላለህ ከነርሱ ጋራ\nአትፍሪ አላት ስለምን ትፍራ\nአምነው ድል ነሱት ያንን መከራ\nአዝ..........\nእኔም አምናለው አድነኝ ብዬ\nቆመህ አማልደኝ ከቸር ጌታዬ\nክፉውን ዘመን የማልፍበት\nፅናትን ስጠኝ ድል ልንሳበት",
