    title: "አረሳት ኢትዮጵያን",
    description: null,
    categoryId: 5,
    mezmurPoem:
      "አረሳት ኢትዮጵያን በዕርፈ መስቀል\nአባ ተክለሐይማኖት ሰባኪ ወንጌል\nየእግዚአብሔር ሰው-ነው ተወዳጅ\nበሰማይ\nየተረማመደ በጽድቅ አደባባይ (2)\nፈውስና ጸሎቱ ቃሉ የተሰማ\nወንጌል የሰበከ በገጠር ከተማ\nየኢቲሣው ኮከብ የደብረ አስቦቱ\nየወንጌል ተዋጋች ንጽሕት ሕይወቱ\nአዝ -------ፋናው እስከ ዛሬ ሲያበራ የኖረው\nየኢቲሣው አባት ፍስሐ ጽዮን ነው\nእግዚእ-ሐርያ እናቱ ማሕፀነ ብሩህ\nወለደች ኮከብን ሲዖልን የሚያውክ\nአዝ -------ዲያቢሎስ እስካሁን ስሙ ሲጠራበት\nሲቃጠል ይኖራል በእሳት ሰንሰለት\nአዲስ ሐዋርያ የኢትዮጵያ አባት\nደጋና ቆላውን በመስቀል ባረካት\nአዝ -------ምንጩና ፏፏቴው ተራራው ቅዱስ\nነው\nየአባታችን መስቀል ጽኑው ስለነካው\nየተራመደበት የዳሰሰው ሁሉ\nድውይ ይፈውሳል ሣርና ቅጠሉ",
    createdAt: "2026-01-10T08:00:00.000Z",
    updatedAt: "2026-01-10T08:00:00.000Z",
