    description: null,
    categoryId: 5,
    mezmurPoem:
      "ስምዓ ጽድቅ ኮንከ /2/ ተክለ\nሃይማኖት\nወበእንተዝ ተሰመይከ /2/ተክለ\nሃይማኖት\nየጽድቅ ምስክር ሆንክ /2/ተክለ\nሃይማኖት\nስለዚህ ተሰየምክ በደብረ መዊእ\nቅድስት",
