    title: "ዜኖኩ ጽድቀከ",
    description: null,
    categoryId: 5,
    mezmurPoem:
      "ዜኖኩ ጽድቀከ ወነገርኩ አድኅኖተከ\nከሠትኩ ቃላቲከ ለሕዝብከ ኢትዮጵያ\n/፪/\nበጸጋሁ ለመንፈስ ቅዱስ\nወመሀርክዎሙ አነ ይቤ ያሬድ\nካህን/፪/\nጽድቅህን ነገርኩ አዳኝነትህን\nአስተማርኩ/፪/\nቃላትህን ለኢትዮጵያ ለሕዝብህ\nገለጥኩ እኔም በመንፈስ ቅዱስ ፀጋ\nአስተማርኩአቸው አለ ያሬድ\nካህን/፪/",
    createdAt: "2026-01-10T08:00:00.000Z",
