    description: null,
    categoryId: 5,
    mezmurPoem:
      "ኖላዊኃ ለኢትዮጵያ (2×)\nተክለሀይማኖት ከመ ጴጥሮስ\nሀዋርያ (4×)\nጠባቂዋ ለኢትዮጵያ እረኛዋ\nለኢትዮጵያ\nተክለሀይማኖት እንደ ጴጥሮስ\nሀዋርያ (4×)\nኖላዊሀ ለኢትዮጵያ (2×)\nተክለሀይማኖት ሐዲስ ሀዋርያ (4×)",
