    mezmurPoem:
      "ተክለሀይማኖት ሃራዊ ምዕመን (2×)\nሃራዌ ምዕመን (4×) ተክለሃይማኖት\nመዋኤ ሰይጣን (2×)\nተክለሀይማኖት አዲስ ሐዋርያ (2×)\nአዲስ ሐዋርያ (4×) ተክለሀይማኖት\nዘኢትዮጵያ (2×)",
