    description: null,
    categoryId: 6,
    mezmurPoem:
      "እምሰማያት ወረደ ወእምማርያም\nተወልደ (2×)\nከመ ይኩንቤዛ (2) ለኩሉ አለም (2×)\nለብሰ ስጋ ማርያም (2×)\nትርጉም፡\nከሰማያት ወረደ ከድንግል ማርያም\nተወልደ\nእንዲሆነን ቤዛ (2) ለዓለሙ ሁሉ\n(2×) ለበሰ የማርያም ስጋ",
