    description: null,
    categoryId: 6,
    mezmurPoem:
      "በጎል ሰከበ በአጽርቅት ተጠብለለ\nቤዛ ኩሉዓለም (2) ዮም ተወልደ\nበበረት ተኛ በጨርቅም ተጠቀለለ\nየአለም መድሃኒት (2×) ዛሬ ተወለደ",
