    title: "በበረት የተኛው",
    description: null,
    categoryId: 6,
    mezmurPoem:
      "በበረት የተኛው ቅዱሱ ሕፃን\nለዓለሙ ሁሉ ሆነልን መድኅን\nምስክር ሊሆነን በፍፁም መንግሥቱ\nትንፋሽ ገበሩለት ከበው እንስሳቱ\nእሰይ የምስራች ሀሌ ሀሌሉያ\nጌታ ተወለደ ከድንግል ማርያም",
    createdAt: "2026-01-10T08:00:00.000Z",
