    mezmurPoem:
      "በቤተልሔም ተወልደ (2) አማኑኤል\nእምዘርዐ ዳዊት (4) ተወልደ\nአማኑኤል\nትርጉም፡በቤተልሔም የተወለደው\nአማኑኤል የዳዊት ዘር ነው፡፡",
