    mezmurPoem:
      "ወወለደት ወልደዘበኩራ (2)\nመንጦላዕተ ደመና ሰወራ (2)\nትርጉም፡ የበኩር ልጅዋን ወለደች\nየደመናም መጋረጃም ሰወራት",
