    title: "በኮከብ መጽኡ",
    description: null,
    categoryId: 6,
    mezmurPoem:
      "በኮከብ መጽኡ (2) ሰብዓሰገል (2)\nለአማኑኤል (4) ይስግዱ ሰብዓሰገል\n(2)\nትርጉም ፡ሰብዓሰገል ለአማኑኤል\nይሰግዱ ዘንድ በኮከብ እየተመሩ\nመጡ",
