    description: null,
    categoryId: 6,
    mezmurPoem: "ውስተ ማኅጸነ ድንግል ኀደረ ማሕጸነ\nድንግል\nሰማይ ወምድር ዘኢያገምሮ (2)\nበማይ ተጠምቀ",
