    title: "ስብሐት",
    description: null,
    categoryId: 6,
    mezmurPoem:
      "ስብሐት ለእግዚአብሔር\nበሰማያት/2/\nወሰላም በምድር ስምረቱ ለሰብ\nሀሌሉያ (4) አሜን ሀሌሉያ",
