    title: "ወአንቲኒ",
    description: null,
    categoryId: 6,
    mezmurPoem:
      "ወአንቲኒ ቤተልሔም ምድረ ኤፍራታ\nእምኔኪ ወጽአ ንጉሠ ይሁዳ አዋልደ\nጢሮስ አሜሐ ይሰግዳ ኩሎሙ ነገስት\n/፪/",
    createdAt: "2026-01-10T08:00:00.000Z",
