    title: "ውእቱ ኢየሱስ",
    description: null,
    categoryId: 6,
    mezmurPoem:
      "ውእቱ ኢየሱስ /፫/ እምቅድስት ድንግል\n\n/፪/ በእንተ ልደቱ ለክርስቶስ ዮም ፍሥሐ\nኮነ በእንተ ልደቱ ለክርስቶስ",
