    description: null,
    categoryId: 7,
    mezmurPoem:
      "በጎል በጎል ሰብዓ ሰገል በጎል ሰብዓ\nሰገል\nበጎል ሰብዓ ሰገል ሰገዱሎቱ\nፀሐይ ፀሐይ ፀሐይ ሰረቀ (2)\nፀሐይ ሰረቀ ክርስቶስ ተጠምቀ\nአንቺ ዮርዳኖስ ምንኛ ታደልሽ (2)\nየእግዚአብሔር መንፈስ ከላይ\nወርዶብሽ\nየዓለም መድኃኒት ተወለደብሽ\nድንግል ማርያም ንፅሕት ቅድስት\nየጌታዬ እናት ምስጋና ይገባሻል\nከሴቶቹ ሁሉ አንቺን መርጦሻል\nእልል እልል ደስ ይበለን (2)\nወንድ ተወልዶ ነፃ አወጣን\nዮሐንስ አጥምቆ ድል አገኘን",
