    description: null,
    categoryId: 7,
    mezmurPoem:
      "ክርስቶስ ትንቢቱ ሲደርስ\nመጣ ከዮርዳኖስ ወደ ዮሐንስ\n\nይሽር ዘንድ የበደልን ደጅ\nገብቶ ተጠመቀ በዮሐንስ እጅ\nወዲያውኑ ተጠምቆ ሲወጣ\nአዋጅ በደመና እንዲህ ብሎ መጣ\nይኸው የምወደው ልጄ\nወደ አለም የላኩት እንዲሞት\nወድጄ\nመንፈስ ቅዱስ በአምሣለ ርግብ\nበራሱ ላይ አድሮ መሰከረ ለህዝብ",
    createdAt: "2026-01-10T08:00:00.000Z",
