    id: 206,
    title: "የማነ ብርሃን",
    description: null,
    categoryId: 7,
    mezmurPoem:
      "የማነ (2) ብርሃን (2)\nሃደረ (2) ሃበ ማርያም\nከሰማይ ወረደ አዳምን ፈልጎ (2)\nበቀድሞ ስልጣኑ ሊያኖረው አስቦ\nሃደረ (2) ሃበ ማርያም\nባለጸጋ ሲሆን የሚችህል ሁሉን (2)\nተጠማ ተራበ ወስዶ የኛን ድካም\nሃደረ (2) ሃበ ማርያም\nዮርዳኖስ ወረደ እንደቃሉ ትንቢት(2)\nባህርም ሸሸችው አልጸናች ከሱ ፊት\nሃደረ (2) ሃበ ማርያም\nዘመናት የቆየ ምስጢር ነበረባት(2)\nየአዳም ውድቀት ጽህፈት የተቀበረባት\nሃደረ (2) ሃበ ማርያም\nሲጠመቅ ዮርዳኖስ ጽፈቷን አገኛት (2)\nእንደሰውነቱ ቆሞ ተረገጣት\nእንደ አምላክነቱ ደግሞም አቀለጣት\nሃደረ (2) ሃበ ማርያም\n\nየቃና ዘገሊላ መዝሙራት",
