    id: 211,
    title: "ቃና ዘገሊላ",
    description: null,
    categoryId: 8,
    mezmurPoem:
      "ቃና ዘገሊላ /2/\nበዚያ በሠርግ ቤት\nተገኝተሻል ድንግል ከልጅሽ ጋራ\nተገኝተሃል ጌታ ከእናትህ ጋራ\nእድምተኞች ሞልተው የተጋበዙት\nሲበሉ ሲጠጡ ወይኑ አልቆባችው\nድንግል እናታችን ቤዛዊተ ዓለም\nአንች ደረስሽለት ሆንሽው አማላጅ\nአዝ =====\n\nአንተ እያለህስ ማፈር የለባቸው\nሁሉም ይቻልሃል ወይኑንሙላላቸው\nማድጋው ባዶ ነው ብለሽ የተናገርሽ\nጌታን ያሳሰብሽው እመቤታችን ነሽ\nአዝ =====\nየጌታን አምላክነት የተገለፀበት\nምንኛ ታደለ የነዶኪማስ ቤት\nዛሬም ይሄው በሰርገኞች ቤት\nበረከት ፈሰሰ በአምላክ ቸርነት\nአዝ =====\nውሃው ተለውጦ ወይን ጠጅ ሲሆን\nበቃና ዘገሊላ ሁላችን አየን\nእግዚአብሔር ከኖረ በመካከላችን\nሁሌ ይሰጠናል ይህን የመሰል ወይን\n\nየዘመነ መርዕዊ",
