    description: null,
    categoryId: 9,
    mezmurPoem:
      "ዳዊት ይሴብሕ ወይዜምር ዕዝራ (2)\nእንዘ ይብሉ ሙሽሪት ሙሽራ (4)\nትርጉም፡-ዳዊት ያመሰግናል ዕዝራም\nይዘምራል ሙሽሪትና ሙሽራ\nበማለት",
    createdAt: "2026-01-10T08:00:00.000Z",
