    mezmurPoem:
      "በምድራዊ ሕይወት/2/ በፈተና ቦታ\nድንግል ትጠብቅህ እጆቿን ዘርግታ\nማርያም ትጠብቅሽ እጆቿን\nዘርግታ/2/",
