    description: null,
    categoryId: 10,
    mezmurPoem:
      "ተናዘዘ ብኪ አኮኑ ህሊና ቀዳማይ\nአብ\nኪዳነምሕረት ማርያም\nኪዳነምሕረት ኪዳነምሕረት\nማርያም ኪዳነአምላክ",
