    mezmurPoem: "ኪዳነ ምሕረት ኩኒ ለሕይወትየ\nፀወነኖ (2×)\nእስመ ተማኅፀንኩ አንሰ\nተማኅፅኖ(2×)",
    createdAt: "2026-01-10T08:00:00.000Z",
