    description: null,
    categoryId: 10,
    mezmurPoem:
      "አንቺ ነሽ ተስፋው ለአዳም ኪዳነ\nምሕረት\nበተሰደደ ጊዜ ከገነት (2×)\nአንቲ ውእቱ ተስፋው ለአዳም\nኪዳነምህረት\nአመ እምሰደድ ከገነት (2×)",
    createdAt: "2026-01-10T08:00:00.000Z",
