    description: null,
    categoryId: 13,
    mezmurPoem:
      "ሰላምሽ ዛሬ ነው ኢየሩሳሌም\nወደንቺ መጥቷልና አምላክ\nዘለዓለም/፪/\nሆሣዕና በአርያም እያሉ ዘመሩ\nህፃናት በኢየሩሳሌም\nአንቺ ቤተልሔም የዳዊት ከተማ\nየሕዝቦችሽ ብርሃን መጣልሽ በግርማ\n\nሆሣዕና እያሉ አመሰገኑት\nበኢየሩሳሌም አእሩግ ህፃናት(፪)\nኪሩቤል መንበሩን የሚሸከሙለት\nመስቀል ተሸከመ ሊሆነን መድኃኒት\nየኢየሱስን ሕማም ደናግልም\nአይተው\nእያለቀሱለት ሄዱ ተከትለው(፪)",
    createdAt: "2026-01-10T08:00:00.000Z",
