    description: null,
    categoryId: 13,
    mezmurPoem:
      "ሆሣዕና/2/በአርያም ሆሣዕና\nበአርያም\nቅድስት ሀገር ሆይ ኢየሩሳሌም\nምስጋናሽ ብዙ ነው በመላው ዓለም\n\nአዝ….\nበአህያ ተቀምጦ ሲመጣ ሲያዩት\nሕጻናት በአንድነት አመሰገኑት\nአዝ….\nሊቃነ ካህናት በጣም ተቆጥተዉ\nይማከሩ ጀመር ብለዉ እንስቀለዉ(2",
    createdAt: "2026-01-10T08:00:00.000Z",
