    mezmurPoem:
      "በትፍሥሕት ቦአ (፪)\nኧኸ /ኢየሱስ/(፫) ኢየሩሳሌም\nትርጉም፦ ኢየሱስ በደስታ ወደ\nኢየሩሳሌም ገባ",
