    description: null,
    categoryId: 15,
    mezmurPoem: "አማን በአማን ተንሥዓ/4 /\nተንሥዓ እምነ ሙታን/4/\nበዓለ ዕርገቱ ለክርስቶስ",
    createdAt: "2026-01-10T08:00:00.000Z",
