    title: "በትፍስሕት",
    description: null,
    categoryId: 15,
    mezmurPoem:
      "በትፍስሕት ወበሐሴት\nይሁቦሙ ኃይለ ወስልጣነ (2)\n\nትርጉም፡ በደስታ ኃይልና ስልጣንን\nይሰጣቸዋል፡፡",
    createdAt: "2026-01-10T08:00:00.000Z",
