      "አንትሙሰ አሀዊነ\n\nባረክናክሙ ውስተ ቤተ\nእግዚአብሔር\n#ትርጉም ፡ እናንተ ወንድሞቻችን\nበእግዚአብሔር ቤት መረቅናችሁ",
