    description: null,
    categoryId: 18,
    mezmurPoem:
      "ጸሎትክሙ ጽንዕት /፪/\nሃይማኖትክሙ ርትዕት\nሃይማኖትክሙ /፪/\nእንተ በኩሉ ትረድዕ በምግባረ\nጽድቅ አግአዚያን አንትሙ\nበምግባረ ጽድቅ /፪/\nትርጉም፡- የጽድቅን ሥራ\nበመሥራት ነፃ የምታወጡ በሁሉ\n\nነገር የምትረዱ ብፁዓን ሊቃነ ጳጳሳት\nጸሎታችሁ የጸናች ሃይማኖታችሁ\nየቀናች ናት",
