    description: null,
    categoryId: 22,
    mezmurPoem:
      "ይቤላ ህፃን ለእሙ\nኢትፍርሂም (2) ነበልባለ እሳት /2/\nለአናንያ ወአዛርያ ወሚሳኤል\nዘአድሃኖሙ ውእቱ ያድነነ\nህፃን እናቱን አላት እናቴ ሆይ አትፍሪ\n(2) የእሳቱን ነበልባል\nአናንያን አዛርያን ሚሳኤልን\nያዳናቸው እኛንም ያድነናል",
    createdAt: "2026-01-10T08:00:00.000Z",
