    description: null,
    categoryId: 22,
    mezmurPoem:
      "ወዓዲ ከመ ኢይማስን ሥጋከ\nዲበ ሠረገላ ኤልያስ ህየ አነብረከ\nትርጉም፡-በኤልያስ ሰረገላ\nአሳርፍሃለሁ ስጋህን እንዲሁ\nአልተወውም",
