    title: "አቁረርከ ቂርቆስ",
    description: null,
    categoryId: 22,
    mezmurPoem:
      "አቁረርከ ቂርቆስ ነበልባሉ ለእቶነ\nእሳት ምውቅ ምውቅ (2)\nከመነደ እሳት አቁረሩ (2)አቁረሩ\nሠለስቱ ደቂቅ ኧኸ ኧኸ\nትርጉም:- ቂርቆስ ሆይ\nየሚያቃጥለውን የእሳቱን ነበልባል\nአቀዘቀዝክ ሠለስቱ ደቂቅ ነደ እሳቱን\nእንዳቀዘቀዙት",
    createdAt: "2026-01-10T08:00:00.000Z",
