    categoryId: 22,
    mezmurPoem:
      "ይቤላ ሕፃን ለእሙ ጥብዒኬ\nእምወኢትናፍቂ (2)\nእምዝ ዳግመ አልቦቱ ኩነኔ አልቦ (2)\nይላታል ሕፃን እናቱን ጨክኚ እናቴ\nአትጠራጠሪ (2)\nከዚህ በኋላ የለብንምና ኩነኔ የለም\n(2)",
