    description: null,
    categoryId: 23,
    mezmurPoem:
      "ደብር ርጉእ ወደብር ጥሉል /፪/\nለምንት ይትነሥኡ ርጉአን\nአድባር/፪/\nደብር ዘሠምሮ እግዚአብሔር\nየኀድር ውስቴቱ እግዚአብሔር /፪/\nትርጉም፡- የጸኑ ተራራዎች ለምን\nይነሣሉ? እግዚአብሔር\nይህን ተራራ ያድርበት ዘንድ\nወደደው በእውነት እግዚአብሔር\nለዘለዓለም ያድርበታል",
