    title: "ወተቀበልዎ",
    description: null,
    categoryId: 29,
    mezmurPoem: "ወተቀበልዎ መላእክት በስብሐት\nወበማኅሌት\nወአብእዎ ኢየሩሳሌም /2/\nሰማያዊት /2/",
    createdAt: "2026-01-10T08:00:00.000Z",
