    title: "ኀዲጎ ብእሲቶ",
    description: null,
    categoryId: 29,
    mezmurPoem:
      "ኀዲጎ ብእሲቶ መኒኖ መንግስቱ\nዘፈለሰ /3/ መኒኖ መንግስቱ\nትርጉም ፡-መንግስቱን እና\nሚስቱን ትቶ መነነ፡፡",
    createdAt: "2026-01-10T08:00:00.000Z",
